// HPC Module Index - client-side app
// Loads data/modules.json (generated by scripts/generate_module_index.py)
// and renders a searchable, filterable browser similar to packages.spack.io

const DATA_URLS = ["../data/modules.json", "./data/modules.json", "/data/modules.json"];

const state = {
  packages: [],
  filtered: [],
  activeCategory: null,
  query: "",
  selected: null,
};

function escapeHtml(str) {
  if (str == null) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

async function loadData() {
  let lastError;
  for (const url of DATA_URLS) {
    try {
      const resp = await fetch(url, { cache: "no-store" });
      if (!resp.ok) continue;
      return await resp.json();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError || new Error("Could not load modules.json from any known location");
}

function buildCategoryCounts(packages) {
  const counts = new Map(); // label -> { count, color }
  for (const pkg of packages) {
    const label = categoryLabel(pkg);
    if (!counts.has(label)) counts.set(label, { count: 0, color: categoryColor(pkg) });
    counts.get(label).count += 1;
  }
  return [...counts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
}

function categoryLabel(pkg) {
  return pkg.category || "uncategorized";
}

function categoryColor(pkg) {
  return (pkg.category_color && pkg.category_color.css) || "#b5b3b3";
}

function packageKey(pkg) {
  return pkg.name;
}

function systemBadges(pkg) {
  return (pkg.systems || [])
    .map((s) => `<span class="system-badge">${escapeHtml(s)}</span>`)
    .join(" ");
}

// Picks black or white text for readable contrast against an arbitrary rgb() background.
function idealTextColor(rgbCss) {
  const match = /rgb\((\d+),\s*(\d+),\s*(\d+)\)/.exec(rgbCss || "");
  if (!match) return "#000";
  const [, r, g, b] = match.map(Number);
  const luminance = 0.299 * r + 0.587 * g + 0.114 * b;
  return luminance > 150 ? "#1b1f23" : "#ffffff";
}

function matchesQuery(pkg, query) {
  if (!query) return true;
  const q = query.toLowerCase();
  if (pkg.name && pkg.name.toLowerCase().includes(q)) return true;
  if (pkg.description && pkg.description.toLowerCase().includes(q)) return true;
  if (categoryLabel(pkg).toLowerCase().includes(q)) return true;
  if (pkg.tags && pkg.tags.some((t) => t.toLowerCase().includes(q))) return true;
  if (pkg.systems && pkg.systems.some((s) => s.toLowerCase().includes(q))) return true;
  return false;
}

function matchesCategory(pkg, category) {
  if (!category) return true;
  return categoryLabel(pkg) === category;
}

function applyFilters() {
  state.filtered = state.packages.filter(
    (pkg) => matchesQuery(pkg, state.query) && matchesCategory(pkg, state.activeCategory)
  );
  renderPackageList();
  renderCategoryList();
  renderMeta();
}

function renderMeta() {
  const meta = document.getElementById("meta");
  meta.textContent = `${state.filtered.length} / ${state.packages.length} modules`;
}

function renderCategoryList() {
  const list = document.getElementById("category-list");
  const counts = buildCategoryCounts(state.packages);
  const items = [`<li data-category="" class="${!state.activeCategory ? "active" : ""}"><span>All</span> <span class="count">${state.packages.length}</span></li>`];
  for (const [cat, { count, color }] of counts) {
    items.push(
      `<li data-category="${escapeHtml(cat)}" class="${state.activeCategory === cat ? "active" : ""}"><span><span class="category-dot" style="background:${escapeHtml(color)}"></span>${escapeHtml(cat)}</span> <span class="count">${count}</span></li>`
    );
  }
  list.innerHTML = items.join("");
  list.querySelectorAll("li").forEach((li) => {
    li.addEventListener("click", () => {
      state.activeCategory = li.dataset.category || null;
      applyFilters();
    });
  });
}

function renderPackageList() {
  const container = document.getElementById("package-list");
  if (!state.filtered.length) {
    container.innerHTML = `<div class="no-results">No modules match your search.</div>`;
    return;
  }
  container.innerHTML = state.filtered
    .map((pkg) => {
      const versionCount = pkg.versions ? pkg.versions.length : 0;
      const isActive = state.selected && packageKey(state.selected) === packageKey(pkg);
      const color = categoryColor(pkg);
      return `
        <div class="package-card ${isActive ? "active" : ""}" data-key="${escapeHtml(packageKey(pkg))}" style="border-left: 4px solid ${escapeHtml(color)}">
          <h3>${escapeHtml(pkg.name)} <span class="version-badge">${versionCount} version${versionCount === 1 ? "" : "s"}</span> ${systemBadges(pkg)}</h3>
          <p>${escapeHtml(pkg.description || "No description available.")}</p>
        </div>`;
    })
    .join("");
  container.querySelectorAll(".package-card").forEach((card) => {
    card.addEventListener("click", () => {
      const pkg = state.packages.find((p) => packageKey(p) === card.dataset.key);
      selectPackage(pkg);
    });
  });
}

function selectPackage(pkg) {
  state.selected = pkg;
  renderDetail();
  renderPackageList();
}

function renderDetail() {
  const pane = document.getElementById("detail-pane");
  const pkg = state.selected;
  if (!pkg) {
    pane.innerHTML = `<div class="detail-placeholder">Select a module to see details.</div>`;
    return;
  }

  const categoryBadge = `<span class="category-badge" style="background:${escapeHtml(categoryColor(pkg))}; color:${idealTextColor(categoryColor(pkg))}">${escapeHtml(categoryLabel(pkg))}</span>`;

  const tags = (pkg.tags || [])
    .map((t) => `<span class="tag">${escapeHtml(t)}</span>`)
    .join("");

  const versions = (pkg.versions || [])
    .map((v) => {
      const loadCmd = `module load ${v.full_name || `${pkg.name}/${v.version}`}`;
      const isDefault = Boolean(v.is_default);
      return `
        <details class="version-row" ${isDefault ? "open" : ""}>
          <summary>
            ${escapeHtml(v.full_name || v.version || "unknown")}
            ${v.system ? `<span class="system-badge">${escapeHtml(v.system)}</span>` : ""}
            ${isDefault ? '<span class="default-badge">default</span>' : ""}
          </summary>
          <div class="load-cmd">${escapeHtml(loadCmd)}</div>
          ${v.help ? `<div class="help-text">${escapeHtml(v.help)}</div>` : ""}
        </details>`;
    })
    .join("");

  pane.innerHTML = `
    <h2>${escapeHtml(pkg.name)}</h2>
    <div class="category-row">${categoryBadge}${systemBadges(pkg)}</div>
    ${pkg.description ? `<p>${escapeHtml(pkg.description)}</p>` : ""}
    ${pkg.url ? `<p class="url"><a href="${escapeHtml(pkg.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(pkg.url)}</a></p>` : ""}
    ${tags ? `<div>${tags}</div>` : ""}
    <div class="detail-section">
      <h4>Versions</h4>
      ${versions || "<p>No version information available.</p>"}
    </div>
  `;
}

function init(data) {
  state.packages = data.packages || [];
  state.filtered = state.packages;
  renderCategoryList();
  renderPackageList();
  renderMeta();

  const search = document.getElementById("search");
  search.addEventListener("input", (e) => {
    state.query = e.target.value.trim();
    applyFilters();
  });
}

loadData()
  .then(init)
  .catch((err) => {
    document.getElementById("package-list").innerHTML =
      `<div class="no-results">Failed to load modules.json: ${escapeHtml(err.message)}</div>`;
    console.error(err);
  });
